INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_guide_user_benchmark_1d
PARTITION (
    grass_region = ${grass_region},
    local_date = ${local_date}
)
SELECT 
/* +BROADCAST(t2) */
    t1.user_id
    ,t1.device_id
    ,t1.platform
    ,t2.final_page_type AS union_page_type
    ,t1.search_entrance
    ,t2.feature_tag
    ,t1.keyword

    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(view_cnt) AS view_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
FROM 
    dwd_search_page_${grass_region_without_quote} t1 
    INNER JOIN dim_search_feature_mapping_${grass_region_without_quote} t2
    ON t1.page_type = t2.page_type
        AND t1.operation = t2.operation
        AND (
            t1.page_section  = t2.page_section
            OR t2.page_section = ''
        )
        AND (
            t1.target_type = t2.target_type
            OR t2.target_type = ''
        )
        AND (
            ARRAY_CONTAINS(t2.in_input_type, t1.input_type)
            OR !ARRAY_CONTAINS(t2.not_in_input_type, t1.input_type) 
            OR t2.input_type = ''
        )
        AND (
            t1.if_shop = t2.if_shop
            OR t2.if_shop = ''
        )
        AND (
            t1.if_shop = t2.if_shop
            OR t2.if_shop = ''
        )
        AND (
            ARRAY_CONTAINS(t2.in_search_entrance, t1.search_entrance)
            OR t2.search_entrance = ''
        )
        AND (
            ARRAY_CONTAINS(t2.in_search_mid, t1.search_mid)
            OR t2.search_mid = ''
        )
        AND (
            ARRAY_CONTAINS(t2.in_content_mix_frame_tab_name, t1.content_mix_frame_tab_name)
            OR !ARRAY_CONTAINS(t2.not_in_content_mix_frame_tab_name, t1.content_mix_frame_tab_name) 
            OR t2.content_mix_frame_tab_name = ''
        )
        AND (
            ARRAY_CONTAINS(t2.in_current_page, t1.current_page)
            OR !ARRAY_CONTAINS(t2.not_in_current_page, t1.current_page) 
            OR t2.current_page = ''
        )
        AND (
            ARRAY_CONTAINS(t2.in_platform, t1.platform)
            OR t2.platform = ''
        )
GROUP BY
    1,2,3,4,5,6,7;
